<?php

namespace Database\Factories;

use App\Enums\IndentPriority;
use App\Enums\IndentStatus;
use App\Models\Indent;
use App\Models\Installation;
use App\Models\Movement;
use App\Models\User;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Indent>
 */
class IndentFactory extends Factory
{
    protected $model = Indent::class;

    public function definition(): array
    {
        return [
            // number will be auto-generated by Indent model creating event if not set
            'title' => fake()->sentence(4),
            'description' => fake()->paragraph(),
            'work_type' => fake()->randomElement([
                'Civil Maintenance',
                'Road Repair',
                'Drainage & Plumbing',
                'Structural Concrete',
                'Painting & Waterproofing',
                'Boundary Wall Construction',
            ]),
            'installation_id' => Installation::factory(),
            'priority' => fake()->randomElement(IndentPriority::cases()),
            'required_by' => fake()->dateTimeBetween('+1 week', '+2 months')->format('Y-m-d'),
            'justification' => fake()->sentence(),
            'status' => IndentStatus::OPEN,
            'is_draft' => false,
            'creator_cpf' => fn () => User::factory()->create()->cpf,
            'current_holder_cpf' => fn () => User::factory()->create()->cpf,
        ];
    }

    /**
     * Set the indent as draft.
     */
    public function draft(): static
    {
        return $this->state(fn () => [
            'is_draft' => true,
        ]);
    }

    /**
     * Set status to Open.
     */
    public function open(): static
    {
        return $this->state(fn () => [
            'status' => IndentStatus::OPEN,
            'is_draft' => false,
        ]);
    }

    /**
     * Set status to Assigned.
     */
    public function assigned(): static
    {
        return $this->state(fn () => [
            'status' => IndentStatus::ASSIGNED,
            'is_draft' => false,
        ]);
    }

    /**
     * Set status to InProgress.
     */
    public function inProgress(): static
    {
        return $this->state(fn () => [
            'status' => IndentStatus::IN_PROGRESS,
            'is_draft' => false,
        ]);
    }

    /**
     * Set status to Closed.
     */
    public function closed(): static
    {
        return $this->state(fn () => [
            'status' => IndentStatus::CLOSED,
            'is_draft' => false,
        ]);
    }

    /**
     * Create an associated movement after creating the indent.
     */
    public function withMovement(array $attributes = []): static
    {
        return $this->afterCreating(function (Indent $indent) use ($attributes) {
            Movement::factory()->create(array_merge([
                'indent_id' => $indent->id,
                'from' => $indent->creator_cpf,
                'to' => $indent->current_holder_cpf,
            ], $attributes));
        });
    }
}
